    }

    // Perform the right rotation
    TreeNode<T> leftChild = node.getLeft();          // The node that will become the new root of this subtree
    TreeNode<T> leftRight = leftChild.getRight();    // This subtree will become the left subtree of the original node

    // Rewire the children
    node.setLeft(leftRight);
    if (leftRight != null) {
        leftRight.setParent(node);
    }

    leftChild.setRight(node);
    leftChild.setParent(node.getParent()); // Keep reference to the original parent if needed

    // Return the new parent of the rotated subtree
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        // Cannot rotate if there is no left child; return node unchanged.
        return node;
    }

    // Perform rotation
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    left.right = node;

    // Update parent links
    left.parent = node.parent;
    if (node.parent != null) {
        if (node.parent.left == node) {
            node.parent.left = left;
        } else if (node.parent.right == node) {
            node.parent.right = left;
        }
    }
    node.parent = left;

    // The new parent of the subtree is 'left'
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.getLeft();
    if (leftChild == null) {
        // Nothing to rotate
        return node;
    }

    // Perform rotation
    node.setLeft(leftChild.getRight());
    if (leftChild.getRight() != null) {
        leftChild.getRight().setParent(node);
    }

    leftChild.setRight(node);

    // Update parent references
    leftChild.setParent(node.getParent());
    node.setParent(leftChild);

    // Return the new root of this subtree
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Basic validation: rotation is only possible if the node and its left child exist
    if (node == null || node.left == null) {
        return node;  // nothing to rotate
    }

    // Store references to nodes involved in the rotation
    TreeNode<T> leftChild   = node.left;
    TreeNode<T> leftRight   = leftChild.right;
    TreeNode<T> nodeParent  = node.parent;

    // Perform the rotation
    leftChild.right = node;       // left child becomes new root of this subtree
    node.left = leftRight;        // original left child's right subtree becomes node's left subtree

    // Update parent pointers
    leftChild.parent = nodeParent;
    node.parent = leftChild;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // Update the original parent to point to the new root
    if (nodeParent != null) {
        if (nodeParent.left == node) {
            nodeParent.left = leftChild;
        } else if (nodeParent.right == node) {
            nodeParent.right = leftChild;
        }
    }

    // Return the new root of the rotated subtree
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        throw new IllegalArgumentException("node has no left child to rotate");
    }

    // Perform rotation
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    leftChild.right = node;

    // Update parent references
    TreeNode<T> parent = node.parent;
    node.parent = leftChild;
    leftChild.parent = parent;

    if (parent != null) {
        if (parent.left == node) {
            parent.left = leftChild;
        } else if (parent.right == node) {
            parent.right = leftChild;
        }
    }

    return leftChild;
}

