public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        // Retrieve basic data from the event
        long timeStamp = 0L;
        try {
            timeStamp = event.getTimeStamp();
        } catch (Exception e) {
            // ignore
        }
        String level = "";
        try {
            level = event.getLevel() != null ? event.getLevel().toString() : "";
        } catch (Exception e) {
            // ignore
        }
        String threadName = "";
        try {
            threadName = event.getThreadName() != null ? event.getThreadName() : "";
        } catch (Exception e) {
            // ignore
        }
        String loggerName = "";
        try {
            loggerName = event.getLoggerName() != null ? event.getLoggerName() : "";
        } catch (Exception e) {
            // ignore
        }
        String message = "";
        try {
            // Prefer formattedMessage if available
            message = event.getFormattedMessage() != null ? event.getFormattedMessage()
                    : (event.getMessage() != null ? event.getMessage() : "");
        } catch (Exception e) {
            // ignore
        }

        // Build the formatted log string
        StringBuilder sb = new StringBuilder();
        sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS").format(new java.util.Date(timeStamp)));
        sb.append(' ');
        sb.append(level);
        sb.append(" [");
        sb.append(threadName);
        sb.append("] ");
        sb.append(loggerName);
        sb.append(" - ");
        sb.append(message);

        return sb.toString();
    } catch (Throwable t) {
        // In case anything goes wrong, return a simple representation
        return "[error formatting log event]";
    }
}

public String format(LoggingEvent event) {
    try {
        if (event == null) {
            return "";
        }

        // Assume the pattern is stored in this instance as `conversionPattern`.
        // If not set, simply return the event message.
        String pattern = (this instanceof PatternAware) ? ((PatternAware) this).getPattern() : null;
        if (pattern == null || pattern.isEmpty()) {
            return event.getFormattedMessage();
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pattern.length(); i++) {
            char ch = pattern.charAt(i);
            if (ch != '%') {
                sb.append(ch);
                continue;
            }
            // Handle escaped %%
            if (i + 1 < pattern.length() && pattern.charAt(i + 1) == '%') {
                sb.append('%');
                i++; // skip next '%'
                continue;
            }

            // Extract specifier (e.g., d, m, p, t, c, n)
            if (i + 1 >= pattern.length()) {
                // Trailing '%' with no specifier; treat as literal
                sb.append('%');
                continue;
            }
            char spec = pattern.charAt(i + 1);
            String replacement;
            switch (spec) {
                case 'm': // Message
                    replacement = event.getFormattedMessage();
                    break;
                case 'd': // Date/Time
                    long ts = event.getTimeStamp();
                    // Use a default date format; you can customize as needed
                    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
                    replacement = sdf.format(new java.util.Date(ts));
                    break;
                case 'p': // Level
                    replacement = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
                    break;
                case 't': // Thread name
                    replacement = Thread.currentThread().getName();
                    break;
                case 'c': // Logger name
                    replacement = event.getLoggerName();
                    break;
                case 'n': // New line
                    replacement = System.lineSeparator();
                    break;
                default: // Unsupported specifier; keep literal
                    replacement = "%" + spec;
                    break;
            }
            sb.append(replacement);
            i++; // Skip specifier
        }
        return sb.toString();
    } catch (Exception ex) {
        // In case of any failure, return a safe representation
        return event != null ? event.getFormattedMessage() : "";
    }
}

public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String time = sdf.format(new java.util.Date(event.getTimeStamp()));
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
        String thread = event.getThreadName() != null ? event.getThreadName() : "unknownThread";
        String logger = event.getLoggerName() != null ? event.getLoggerName() : "unknownLogger";
        String message = event.getFormattedMessage() != null ? event.getFormattedMessage() : "";
        return String.format("%s %-5s [%s] %s - %s", time, level, thread, logger, message);
    } catch (Exception e) {
        // Fallback: return just the message
        String fallback = event.getFormattedMessage();
        return fallback != null ? fallback : "";
    }
}

public String format(LoggingEvent event) {
    if (event == null) {
        return "[null LoggingEvent]";
    }
    try {
        StringBuilder sb = new StringBuilder();
        sb.append("[")
          .append(event.getTimeMillis())
          .append("] ");
        if (event.getLevel() != null) {
            sb.append("[")
              .append(event.getLevel())
              .append("] ");
        }
        String loggerName = event.getLoggerName();
        sb.append("[")
          .append(loggerName != null ? loggerName : "unknown")
          .append("] ");
        if (event.getMessage() != null) {
            sb.append(event.getMessage().getFormattedMessage());
        } else {
            sb.append("[no message]");
        }
        Throwable thrown = event.getThrown();
        if (thrown != null) {
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            thrown.printStackTrace(pw);
            pw.flush();
            sb.append(System.lineSeparator()).append(sw.toString());
        }
        return sb.toString();
    } catch (Exception e) {
        return "[Error formatting LoggingEvent: " + e + "]";
    }
}

