    // In the most common case, an HttpServletRequest instance is available as a field named "request".
    // We'll safely handle all possible nulls or malformed inputs and default to 0 if we cannot determine a valid length.
    try {
        // If a request object exists, try the built‑in method that returns a long.
        if (request != null) {
            long len = request.getContentLengthLong();
            if (len >= 0) {
                return len;
            }
            // For older servlet containers (<= 3.0) the content length may be returned as an integer:
            // fallback to the header if the long value is negative (i.e., not set).
            String header = request.getHeader("Content-Length");
            if (header != null) {
                try {
                    return Long.parseLong(header.trim());
                } catch (NumberFormatException ignored) {
                }
            }
        }
    } catch (Exception ignore) {
        // Any unexpected exception is swallowed, and 0 will be returned.
    }
    return 0L;
}

