private int parseEndOfLine(String headerPart, int end) {
    // Validate input parameters
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds: " + end);
    }

    // Find the CRLF sequence starting at or after the given end index
    int lineEndIndex = headerPart.indexOf("\r\n", end);

    // Return -1 if the sequence is not found
    return lineEndIndex;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || headerPart.isEmpty()) {
        return -1;
    }
    if (end < 0) {
        end = 0;
    } else if (end > headerPart.length()) {
        return -1;
    }

    int length = headerPart.length();
    for (int i = end; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }

    // Check if the last character itself is a '\r' and there is no following '\n'
    if (end < length && headerPart.charAt(end) == '\r' && end == length - 1) {
        return end;
    }

    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        return -1;
    }
    int len = headerPart.length();
    if (end < 0 || end >= len) {
        return -1;
    }

    int i = end;
    while (i < len) {
        // Find the next carriage return
        int crIndex = headerPart.indexOf('\r', i);
        if (crIndex == -1) {
            // No more CR, so line terminator not found
            return -1;
        }

        // Ensure we have a following LF
        if (crIndex + 1 < len && headerPart.charAt(crIndex + 1) == '\n') {
            return crIndex;
        }

        // If a CR is not followed by an LF, continue searching after this CR
        i = crIndex + 1;
    }

    return -1;
}

private int parseEndOfLine(String headerPart, int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds");
    }
    for (int i = end; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1; // not found
}

private int parseEndOfLine(String headerPart, int end){
    if (headerPart == null) {
