public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Input graph must not be null");
    }
    // An identity mapping is simply a mapping from the graph onto itself.
    // The IsomorphicGraphMapping constructor that accepts a source and target graph is expected to
    // create a mapping that maps each vertex and edge to the corresponding one in the target.
    // Using the same graph for both parameters produces an identity mapping.
    return new IsomorphicGraphMapping<V,E>(graph, graph);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null){
        throw new IllegalArgumentException("Graph must not be null");
    }
    try{
        java.util.Map<V,V> vertexMap = new java.util.HashMap<>();
        for (V v : graph.vertexSet()){
            vertexMap.put(v, v);
        }
        java.util.Map<E,E> edgeMap = new java.util.HashMap<>();
        for (E e : graph.edgeSet()){
            edgeMap.put(e, e);
        }
        // The GraphMapping constructor creates an isomorphism mapping from the source to the destination graph.
        return new org.jgrapht.alg.isomorphism.GraphMapping<>(graph, graph, vertexMap, edgeMap);
    } catch (Exception ex){
        throw new RuntimeException("Failed to create identity mapping", ex);
    }
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Input graph must not be null");
    }
    try {
        IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
        for (V v : graph.vertexSet()) {
            if (!mapping.mapVertex(v, v)) {
                throw new IllegalStateException("Failed to map vertex: " + v);
            }
        }
        for (E e : graph.edgeSet()) {
            if (!mapping.mapEdge(e, e)) {
                throw new IllegalStateException("Failed to map edge: " + e);
            }
        }
        return mapping;
    } catch (Exception ex) {
        throw new RuntimeException("Unable to create identity mapping", ex);
    }
}

