public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap cannot be null");
    }
    try {
        // Create two partitions – left (U) and right (V) – each with two vertices
        // Assumes that V can be represented by a String (common in JGraphT test cases).
        for (int i = 1; i <= 2; i++) {
            @SuppressWarnings("unchecked")
            V u = (V) ("U" + i);
            target.addVertex(u);
            resultMap.put("U" + i, u);
        }
        for (int i = 1; i <= 2; i++) {
            @SuppressWarnings("unchecked")
            V v = (V) ("V" + i);
            target.addVertex(v);
            resultMap.put("V" + i, v);
        }

        // Add all edges between the two partitions (complete bipartite)
        for (int i = 1; i <= 2; i++) {
            @SuppressWarnings("unchecked")
            V src = (V) ("U" + i);
            for (int j = 1; j <= 2; j++) {
                @SuppressWarnings("unchecked")
                V dest = (V) ("V" + j);
                target.addEdge(src, dest);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

