public void generateGraph(Graph<V, E> target, java.util.Map<String, V> resultMap) {
    try {
        // Define the sizes of the two partitions
        final int leftSize = 3;
        final int rightSize = 3;

        java.util.ArrayList<V> leftVertices = new java.util.ArrayList<>(leftSize);
        java.util.ArrayList<V> rightVertices = new java.util.ArrayList<>(rightSize);

        // Add vertices to the left partition
        for (int i = 0; i < leftSize; i++) {
            V v = target.addVertex(); // assume Graph has addVertex() that returns the vertex
            leftVertices.add(v);
            resultMap.put("left" + i, v);
        }

        // Add vertices to the right partition
        for (int i = 0; i < rightSize; i++) {
            V v = target.addVertex();
            rightVertices.add(v);
            resultMap.put("right" + i, v);
        }

        // Connect every vertex of the left partition to every vertex of the right partition
        for (V l : leftVertices) {
            for (V r : rightVertices) {
                try {
                    target.addEdge(l, r);
                } catch (Exception e) {
                    // Edge already exists or graph type prohibits the edge; ignore
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    try {
        // Partition the vertices into two sets based on key prefixes.
        // Keys starting with "A" or "L" (case-insensitive) belong to the left set.
        // Keys starting with "B" or "R" belong to the right set.
        // All other keys are ignored for bipartite construction.
        Set<V> leftSet = new HashSet<>();
        Set<V> rightSet = new HashSet<>();

        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            if (key == null) {
                continue;
            }
            String upper = key.toUpperCase();
            V vertex = entry.getValue();
            if (vertex == null) {
                continue;
            }

            if (upper.startsWith("A") || upper.startsWith("L")) {
                leftSet.add(vertex);
            } else if (upper.startsWith("B") || upper.startsWith("R")) {
                rightSet.add(vertex);
            }
        }

        // Add all vertices to the graph (if not already present).
        for (V v : leftSet) {
            target.addVertex(v);
        }
        for (V v : rightSet) {
            target.addVertex(v);
        }

        // Create edges between every vertex in the left set and every vertex in the right set.
        for (V u : leftSet) {
            for (V v : rightSet) {
                // Avoid duplicate edges in case the graph is undirected.
                if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception ex) {
        // Wrap any unexpected exception to avoid leaking unchecked exceptions.
        throw new RuntimeException("Failed to generate complete bipartite graph", ex);
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null.");
    }

    // Separate vertices into two partitions based on the key prefix
    List<V> leftVertices = new ArrayList<>();
    List<V> rightVertices = new ArrayList<>();

    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (vertex == null) {
            continue; // Skip null vertices
        }
        // Add vertices to the graph if not already present
        try {
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
        } catch (RuntimeException re) {
            // Log or handle exception if needed; skip this vertex
            continue;
        }

        if (key != null) {
            if (key.startsWith("L") || key.startsWith("l")) {
                leftVertices.add(vertex);
            } else if (key.startsWith("R") || key.startsWith("r")) {
                rightVertices.add(vertex);
            } else {
                // If the key doesn't clearly belong to a partition, we can guess by
                // putting it in the first non-empty list or skip it.
                // For simplicity, assign to left if left is empty, otherwise right.
                if (leftVertices.isEmpty()) {
                    leftVertices.add(vertex);
                } else {
                    rightVertices.add(vertex);
                }
            }
        } else {
            // No key, assign arbitrarily to left
            leftVertices.add(vertex);
        }
    }

    // If only one partition was identified, we cannot create bipartite edges
    if (leftVertices.isEmpty() || rightVertices.isEmpty()) {
        return;
    }

    // Create all possible edges between vertices of different partitions
    for (V u : leftVertices) {
        for (V v : rightVertices) {
            try {
                if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
                    target.addEdge(u, v);
                }
            } catch (RuntimeException re) {
                // Edge addition failed; ignore and continue
            }
        }
    }
}

protected int findByte(byte value, int pos) {
    // Return -1 immediately if the buffer has not been initialized.
    if (buffer == null) {
        return -1;
    }

    int length = buffer.length;

    // If the starting position is outside the bounds of the buffer, no search can be performed.
    if (pos < 0 || pos >= length) {
        return -1;
    }

    // Scan forward from the starting position looking for the target byte.
    for (int i = pos; i < length; i++) {
        if (buffer[i] == value) {
            return i; // Found a match – return its absolute index.
        }
    }

    // No match found.
    return -1;
}

