public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Compute the serialized size of the message
    int size = schema.getSerializedSize(message);

    // Write the size as a varint to the OutputStream
    int tempSize = size;
    while ((tempSize & ~0x7F) != 0) {
        out.write((tempSize & 0x7F) | 0x80);
        tempSize >>>= 7;
    }
    out.write(tempSize);

    // Write the actual serialized message
    schema.writeTo(out, message, buffer);

    // Optional: flush if necessary (depending on caller's needs)
    // out.flush(); // comment or uncomment based on context

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    int size = schema.getSerializedSize(message, buffer);
    // Write the length prefix as a varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Write the message itself
    schema.write(message, out, buffer);
    return size;
}

