public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non‑negative");
    }
    if (len > str.length() - index) {
        throw new IllegalArgumentException("Index + length exceeds string length");
    }

    int end = index + len;
    int byteCount = 0;
    int i = index;
    int remaining = len;

    while (remaining > 0 && i < end) {
        char ch = str.charAt(i);
        int codePoint;
        // Check for surrogate pair
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i += 2; // consumed two chars
        } else {
            codePoint = ch;
            i += 1; // consumed one char
        }
        remaining--;

        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else { // supplementary characters
            byteCount += 4;
        }
    }

    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", length=" + str.length());
    }
    int utf8Bytes = 0;
    int offset = index;
    final int end = index + len;
    while (offset < end) {
        final char ch = str.charAt(offset);
        final int cp;
        if (Character.isHighSurrogate(ch)) {
            if (offset + 1 < end && Character.isLowSurrogate(str.charAt(offset + 1))) {
                cp = Character.toCodePoint(ch, str.charAt(offset + 1));
                offset += 2;
            } else {
                // Unpaired high surrogate – replace with U+FFFD.
                cp = 0xFFFD;
                offset += 1;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate – replace with U+FFFD.
            cp = 0xFFFD;
            offset += 1;
        } else {
            cp = ch;
            offset += 1;
        }
        utf8Bytes += utf8ByteLength(cp);
    }
    return utf8Bytes;
}

private static int utf8ByteLength(int cp) {
    if (cp <= 0x7F) {
        return 1;
    }
    if (cp <= 0x7FF) {
        return 2;
    }
    if (cp <= 0xFFFF) {
        return 3;
    }
    if (cp <= 0x10FFFF) {
        return 4;
    }
    // For invalid codepoints, count as replacement character U+FFFD (3 bytes).
    return 3;
}

