private static String substitute(String value, Properties props, java.util.Set<String> seen) {
    StringBuilder result = new StringBuilder();
    int pos = 0;
    while (true) {
        int start = value.indexOf("${", pos);
        if (start < 0) {
            result.append(value.substring(pos));
            break;
        }
        result.append(value.substring(pos, start));
        int end = value.indexOf("}", start + 2);
        if (end < 0) {
            // No closing brace, treat rest as literal
            result.append(value.substring(start));
            break;
        }
        String varName = value.substring(start + 2, end);
        if (seen.contains(varName)) {
            throw new IllegalStateException("Circular reference detected for variable: " + varName);
        }
        seen.add(varName);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(substitute(varValue, props, seen));
        } else {
            // If variable not found, keep placeholder intact
            result.append("${").append(varName).append("}");
        }
        seen.remove(varName);
        pos = end + 1;
    }
    return result.toString();
}

