private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int tlen = str.length();
    int slen = suffix.length();
    if (slen > tlen) {
        return false;
    }
    return str.regionMatches(ignoreCase, tlen - slen, suffix, 0, slen);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    // both null -> true, one null -> false
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    // suffix longer than str cannot be a suffix
    if (suffixLen > strLen) {
        return false;
    }
    // use regionMatches for optional case-insensitivity
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Return true only when both are null; otherwise false if either is null
    if (str == null) {
