    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    // If suffix length is greater than string length, cannot match
    if (suffixLen > strLen) {
        return false;
    }
    // Use regionMatches to handle case-insensitivity efficiently
    // The offset is the index in str where the potential suffix starts
    int offset = strLen - suffixLen;
    return str.regionMatches(ignoreCase, offset, suffix, 0, suffixLen);
}

