    // If both are null, they are considered to match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null and the other is not, they don't match
    if (str == null || suffix == null) {
        return false;
    }

    // Quick length check – a suffix longer than the string can never match
    final int strLen = str.length();
    final int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }

    // Compute the starting index for the comparison
    final int offset = strLen - suffLen;

    // Compare the relevant substrings, respecting ignoreCase flag
    if (ignoreCase) {
        return str.regionMatches(true, offset, suffix, 0, suffLen);
    } else {
        return str.regionMatches(false, offset, suffix, 0, suffLen);
