    // If the source string is null, only return true if both are null
    if (str == null) {
        return suffix == null;
    }
    // If the suffix is null but str is not, return false
    if (suffix == null) {
        return false;
    }

    int strLen = str.length();
    int suffixLen = suffix.length();

    // A longer suffix cannot match the end of a shorter string
    if (suffixLen > strLen) {
