    int start = strLen - suffixLen;

    // regionMatches handles both case-sensitive and case-insensitive comparison
    return str.regionMatches(ignoreCase, start, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1;
    }
    String remaining = path.substring(start);
    // Split on '/' and ignore empty segments (which can occur at the end or if double slashes)
    String[] parts = remaining.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decodedPart = part;
        if (decode) {
            try {
                decodedPart = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, fall back to the raw part
                decodedPart = part;
            }
        }
        segments.add(new PathSegmentImpl(decodedPart));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path;
    try {
        // Use raw path when decoding is not desired, otherwise use decoded path
        path = decode ? u.getPath() : u.getRawPath();
    } catch (Exception e) {
        // In case of any unexpected exception, return an empty list
        return segments;
    }
    if (path == null || path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            // Skip empty segments which could be caused by a leading '/' or consecutive slashes
            continue;
        }
        segments.add(new PathSegmentImpl(part));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    String rawPath = u.getRawPath(); // preserves percent-encodings
    if (rawPath == null || rawPath.isEmpty()) {
        return segments; // empty list for no path
    }
    // remove leading '/' if present, as it is not a delimiter of a segment
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return segments;
    }
    String[] parts = rawPath.split("/", -1); // keep empty segments
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is always supported, but wrap in runtime exception just in case
                throw new RuntimeException("UTF-8 decoding not supported", e);
            }
        }
        // Create a PathSegmentImpl instance from the segment
        // Assuming a constructor that accepts the segment string
        PathSegmentImpl p = new PathSegmentImpl(seg);
        segments.add(p);
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Validate input URI
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }

    // Get the path component of the URI.  If null or empty we return an empty list.
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }

    // For absolute paths, the leading '/' is ignored and is not considered a delimiter.
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }

    // Split the path into segments.  We keep empty segments which may be useful
    // for paths that end with a slash.
    String[] rawSegments = path.split("/", -1);
    List<PathSegmentImpl> result = new ArrayList<>(rawSegments.length);

    for (String raw : rawSegments) {
        String segment = raw;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(raw, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; wrap as unchecked.
                throw new IllegalArgumentException("UTF-8 encoding not supported", e);
            }
        }
        result.add(new PathSegmentImpl(segment));
    }

    return result;
}

