public InputStream next() throws IOException {
    // If the iterator over files is not initialized, simply return null.
    if (fileIterator == null) {
        return null;
    }

    // Iterate over the remaining files.
    while (fileIterator.hasNext()) {
        java.io.File file = fileIterator.next();

        // Skip null file entries.
        if (file == null) {
            continue;
        }

        try {
            // Return a new FileInputStream for the next available file.
            return new java.io.FileInputStream(file);
        } catch (java.io.FileNotFoundException e) {
            // If the file cannot be opened, skip it and continue searching.
            // The exception is wrapped in IOException to satisfy the throws clause.
            continue;
        }
    }

    // No more files available.
    return null;
}

