public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (shift < 64) {
        byte b = readRawByte();
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint too long");
}

public long readRawVarint64() throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        int b = readRawByte(); // read a single byte from the underlying source
        if ((b & 0x80) == 0) {
            return result | (((long) b) << shift);
        }
        result |= (((long) (b & 0x7F)) << shift);
    }
    // If we get here, the varint was too long or malformed.
