private void pop(final String descriptor) {
    // Ensure descriptor is valid and convert it into a sequence of slot counts to consume.
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int i = 0;
    int slotsToPop = 0;
    if (descriptor.charAt(0) == '(') { // method descriptor – pop argument types
        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            int size = typeSize(descriptor, i);
            if (size < 0) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            slotsToPop += size;
            i = skipType(descriptor, i);
        }
        if (i >= descriptor.length() || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
    } else { // single type descriptor
        int size = typeSize(descriptor, i);
        if (size < 0) {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        slotsToPop += size;
        i = skipType(descriptor, i);
        if (i != descriptor.length()) {
            throw new IllegalArgumentException("Extra characters in descriptor: " + descriptor);
        }
    }

    // Update the frame stack depth, ensuring we never underflow.
    if (outputStackSize < slotsToPop) {
        throw new IllegalStateException(
                "Attempted to pop " + slotsToPop + " slots from a frame with depth " + outputStackSize);
    }
    outputStackSize -= slotsToPop;
}

private int typeSize(String descriptor, int index) {
    if (index >= descriptor.length()) {
        return -1;
    }
    char c = descriptor.charAt(index);
    switch (c) {
        case 'J':
        case 'D':
            return 2;
        case 'I':
        case 'F':
        case 'S':
        case 'C':
        case 'Z':
        case 'B':
        case 'L':
        case '[':
            return 1;
        default:
            return -1;
    }
}

