protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Validate input arguments
    if (sourceVertex == null) {
        throw new IllegalArgumentException("Source vertex cannot be null");
    }
    if (targetVertex == null) {
        throw new IllegalArgumentException("Target vertex cannot be null");
    }
    if (e == null) {
        throw new IllegalArgumentException("Edge cannot be null");
    }

    /* 
     * The data structure that holds the index is assumed to be a 
     * Map that maps a source vertex to another Map that maps a target 
     * vertex to a collection of edges.  The field name is expected to be
     * 'index'; adjust if a different name is used in the surrounding class.
     *
     * Example:
     *   protected Map<V, Map<V, Set<E>>> index = new HashMap<>();
     */

    // Retrieve or create the map for the source vertex
    Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());

    // Retrieve or create the edge set for the target vertex
    Set<E> edgeSet = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());

    // Add the edge to the set
    edgeSet.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Guard against null arguments
    if (sourceVertex == null || targetVertex == null || e == null) {
        return;
    }

    // Assume there is a field in the class of type Map<V, List<E>> called `edgeIndex`
    // that maps a vertex to all incident edges. If such a field does not exist,
    // this method will not compile; the implementation is intended to illustrate
    // how one would typically add an edge to an index.
    edgeIndex.computeIfAbsent(sourceVertex, k -> new ArrayList<>()).add(e);

    // For an undirected graph, also index the edge under the target vertex.
    // The equality check prevents adding the same edge twice when source and
    // target are the same vertex (self-loop).
    if (!sourceVertex.equals(targetVertex)) {
        edgeIndex.computeIfAbsent(targetVertex, k -> new ArrayList<>()).add(e);
    }
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null) {
        throw new IllegalArgumentException("sourceVertex must not be null");
    }
    if (targetVertex == null) {
        throw new IllegalArgumentException("targetVertex must not be null");
    }
    if (e == null) {
        throw new IllegalArgumentException("edge must not be null");
    }

    // Retrieve or create the nested map that holds target vertices for the given source
    Map<V, Set<E>> targetMap = index.get(sourceVertex);
    if (targetMap == null) {
        targetMap = new HashMap<>();
        index.put(sourceVertex, targetMap);
    }

    // Retrieve or create the set of edges for the target vertex
    Set<E> edgesForTarget = targetMap.get(targetVertex);
    if (edgesForTarget == null) {
        edgesForTarget = new HashSet<>();
        targetMap.put(targetVertex, edgesForTarget);
    }

    // Add the edge to the set
    edgesForTarget.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("sourceVertex, targetVertex and e cannot be null");
    }
    // Ensure the index map for the source vertex exists
    Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
    // Ensure the list/set for the target vertex exists
    Set<E> edges = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());
    edges.add(e);
}

