public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }

    // Retrieve the min/max coordinates of the box
    float minX = box.getMinX();
    float maxX = box.getMaxX();
    float minY = box.getMinY();
    float maxY = box.getMaxY();

    // If the box has no width, just return two copies
    if (minX == maxX) {
        return new Pair<>(box, box);
    }

    // Compute the midpoint along the X-axis
    float midX = (minX + maxX) * 0.5f;

    // Construct the left and right sub-boxes
    Box2D left = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);

    return new Pair<>(left, right);
}

