public static int nextPrime(int desiredCapacity){
    try{
        if (desiredCapacity <= 2){
            return 2;
        }
        int n = desiredCapacity;
        if (n % 2 == 0){
            n++;
        }
        while (true){
            if (isPrime(n)){
                return n;
            }
            // Increment by 2 to skip even numbers
            n += 2;
            // Guard against integer overflow
            if (n < 0){
                throw new IllegalArgumentException("Desired capacity too large to find a prime");
            }
        }
    }catch(Exception e){
        // In case of unexpected errors return a safe prime
        return 2;
    }
}

private static boolean isPrime(int number){
    if (number <= 1){
        return false;
    }
    if (number <= 3){
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0){
        return false;
    }
    int i = 5;
    int w = 2;
    while (i * i <= number){
        if (number % i == 0){
            return false;
        }
        i += w;
        w = 6 - w; // alternate adding 2 and 4
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        int n = candidate;
        boolean isPrime;
        if (n <= 3) {
            isPrime = n > 1;
        } else if (n % 2 == 0 || n % 3 == 0) {
            isPrime = false;
        } else {
            isPrime = true;
            for (int i = 5; (long) i * i <= n; i += 6) {
                if (n % i == 0 || n % (i + 2) == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Move to the next odd number
        // The maximum odd integer is Integer.MAX_VALUE (prime), so we will stop before overflow
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity){
    // Handle non-positive or very small values up front
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Start checking at the requested capacity (or the next odd number if even)
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // skip even numbers beyond 2
    }

    while (candidate > 0) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Guard against integer overflow when looking for the next candidate
        if (candidate >= Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("No prime number could be found within the integer range");
        }
        candidate += 2; // continue with only odd numbers
    }

    // If the loop exits unexpectedly, throw an exception
    throw new IllegalArgumentException("Could not find a prime number");
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) { // quick elimination of multiples of 2 and 3
        return false;
    }
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

