public void init() {
    try {
        // Retrieve the distribution path from configuration
        String pathStr = Config.get("distPath");
        if (pathStr == null || pathStr.trim().isEmpty()) {
            throw new IllegalArgumentException("Missing or empty 'distPath' configuration");
        }

        Path distPath = Paths.get(pathStr);

        // If the path does not exist, attempt to create it
        if (!Files.exists(distPath)) {
            Files.createDirectories(distPath);
        } else if (!Files.isDirectory(distPath)) {
            throw new IllegalStateException("'distPath' exists but is not a directory: " + distPath);
        }

        // Store the validated/created path for later use
        this.distPath = distPath;
    } catch (IOException e) {
        throw new RuntimeException("Failed to initialize distribution path", e);
    } catch (Exception e) {
        throw new RuntimeException("Initialization error", e);
    }
}

