public void init() {
    try {
        // Determine distribution path; fallback to "dist" if not set
        String distPath = System.getProperty("dist.path");
        if (distPath == null || distPath.isEmpty()) {
            distPath = "dist";
        }

        // Ensure the distribution directory exists
        java.io.File distDir = new java.io.File(distPath);
        if (!distDir.exists()) {
            if (!distDir.mkdirs()) {
                throw new RuntimeException("Failed to create distribution directory: " + distDir.getAbsolutePath());
            }
        }

        // Store absolute path back to system property for consistent access
        System.setProperty("dist.path", distDir.getAbsolutePath());
    } catch (Exception e) {
        // Log the error and rethrow as runtime exception
        System.err.println("Initialization error: " + e.getMessage());
        e.printStackTrace();
        throw new RuntimeException("Could not initialize configuration", e);
    }
}

