    // Reading length prefixes the string; a negative length indicates a null value.
    int length = in.readInt();
    if (length < 0) {
        return null;
    }
    if (length == 0) {
        return "";
    }
    byte[] bytes = new byte[length];
    int readSoFar = 0;
    while (readSoFar < length) {
        int read = in.read(bytes, readSoFar, length - readSoFar);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        readSoFar += read;
    }
