private Map<String,Object> buildContent(JsonObject jsonObject) {
    Map<String,Object> result = new java.util.HashMap<>();
    if (jsonObject == null) {
        return result;
    }
    try {
        for (java.util.Map.Entry<String, com.google.gson.JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            com.google.gson.JsonElement element = entry.getValue();
            if (element == null || element.isJsonNull()) {
                result.put(key, null);
                continue;
            }
            Object value;
            if (key.equals("ats")) {
                // If the field is 'ats', replace its value with "someone"
                value = "someone";
            } else {
                value = convertJsonElement(element);
            }
            result.put(key, value);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return what has been collected so far
    }
    return result;
}

private Object convertJsonElement(com.google.gson.JsonElement element) {
    if (element == null || element.isJsonNull()) {
        return null;
    }
    if (element.isJsonPrimitive()) {
        com.google.gson.JsonPrimitive prim = element.getAsJsonPrimitive();
        if (prim.isString()) {
            return prim.getAsString();
        } else if (prim.isNumber()) {
            return prim.getAsNumber();
        } else if (prim.isBoolean()) {
            return prim.getAsBoolean();
        }
        return prim.getAsString(); // fallback
    }
    if (element.isJsonObject()) {
        return buildContent(element.getAsJsonObject());
    }
    if (element.isJsonArray()) {
        java.util.List<Object> list = new java.util.ArrayList<>();
        for (com.google.gson.JsonElement item : element.getAsJsonArray()) {
            list.add(convertJsonElement(item));
        }
        return list;
    }
    return null;
}

