private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    // Integer.numberOfLeadingZeros returns the number of leading zero bits
    // in the 32‑bit representation of n. Subtracting from 32 gives the
    // number of bits needed to represent n, which is floor(log2(n)) + 1.
    return 32 - Integer.numberOfLeadingZeros(n);
}

