protected int removeUnusedNodes(){
    int removedCount = 0;
    try {
        // If the tree does not have a root, nothing to do
        if (this.root == null) {
            return 0;
        }
        // If the root itself is inactive, drop the entire tree
        if (!this.root.isActive()) {
            this.root = null;
            return 1;
        }
        removedCount = removeFromNode(this.root, null);
    } catch (Exception e) {
        // In case of any unexpected runtime issue, we return 0
        return 0;
    }
    return removedCount;
}

private int removeFromNode(Category node, Category parent){
    if (node == null) {
        return 0;
    }
    // If this node is inactive, remove it from its parent's children list
    if (!node.isActive()){
        if (parent != null) {
            parent.getChildren().remove(node);
        }
        return 1; // current node removed
    }

    // Otherwise, recursively process the children.
    int removed = 0;
    List<Category> children = node.getChildren();
    for (int i = 0; i < children.size(); ) {
        Category child = children.get(i);
        int childRemoved = removeFromNode(child, node);
        removed += childRemoved;
        // If the child remained active, move to the next index.
        // If it was removed, the list size decreased; hence keep i unchanged.
        if (child.isActive()){
            i++;
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    // Attempts to remove all inactive nodes from the Category tree.
    // Returns the number of nodes removed.
    try {
        // Assume there is a field named 'root' representing the tree's root node.
        // If the tree is empty, nothing to remove.
        if (root == null) {
            return 0;
        }

        // Use a helper to recursively remove inactive nodes.
        return removeFromNode(root);
    } catch (Exception e) {
        // In practice, log the exception. For safety, return 0 if something goes wrong.
        return 0;
    }
}

private int removeFromNode(Category node) {
    if (node == null) {
        return 0;
    }

    int removedCount = 0;
    // Retrieve the list of children.  We assume a public method {@code getChildren()}
    // that returns a mutable java.util.List<Category>.
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }

    // Iterate in reverse so that removal does not affect indices of yet-to-be-checked nodes.
    for (int i = children.size() - 1; i >= 0; i--) {
        Category child = children.get(i);
        if (child == null) {
            continue;
        }
        // If the child is inactive, remove it and increment the count.
        if (!child.isActive()) {
            children.remove(i);
            removedCount++;
        } else {
            // If the child is active, recurse into its subtree.
            removedCount += removeFromNode(child);
        }
    }

    return removedCount;
}

protected int removeUnusedNodes() {
    int removed = 0;
    if (root == null) {
        return 0;
    }
    try {
        removed = removeFromNode(root);
    } catch (Exception e) {
        // Handle any unexpected runtime issues while pruning the tree
        // (e.g., logging can be added here)
    }
    return removed;
}

private int removeFromNode(Category node) {
    if (node == null) {
        return 0;
    }
    int count = 0;
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        if (!child.isActive()) {
            it.remove(); // Remove the inactive node from its parent
            count++;     // Count the removed node
        } else {
            count += removeFromNode(child); // Recurse into active child
        }
    }
    return count;
}

