    if (n < 0) {
        throw new IllegalArgumentException("Negative input is not allowed.");
    }
    java.math.BigInteger fact = java.math.BigInteger.ONE;
    for (int i = 2; i <= n; i++) {
        fact = fact.multiply(java.math.BigInteger.valueOf(i));
    }
    if (fact.compareTo(java.math.BigInteger.valueOf(Long.MAX_VALUE)) > 0) {
        throw new ArithmeticException("Result exceeds the range of a long.");
    }
    return fact.longValue();
