    }

    double totalWeight = 0.0;

    // Iterate over each vertex in the set and sum its incoming edge weights
    for (V vertex : v) {
        if (vertex == null) {
            // Skip null entries within the set
            continue;
        }

        // Assuming we have a data structure that maps a vertex to a map of
        // its incoming edges (source vertex -> weight). For example:
        // Map<V, Map<V, Double>> incomingEdges;
        //
        // Retrieve the map of incoming edges for this vertex
        Map<V, Double> incoming = this.incomingEdges.get(vertex);

        if (incoming != null) {
            for (Double weight : incoming.values()) {
                if (weight != null) {
                    totalWeight += weight;
                }
