            // In BasicCategory the appenders field is a Hashtable
            org.apache.log4j.BasicCategory basic = (org.apache.log4j.BasicCategory) this;
            java.util.Hashtable<?, ?> ht = basic.appenders;
            if (ht != null) {
                synchronized (ht) {
                    java.util.Enumeration<?> e = ht.elements();
                    while (e != null && e.hasMoreElements()) {
                        Object o = e.nextElement();
                        if (o instanceof org.apache.log4j.Appender) {
                            ((org.apache.log4j.Appender) o).doAppend(event);
