    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    // If the minimum label is already 0, nothing to do
    if (minLabel == 0) {
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return; // nothing to move
    }

    // Ensure the target bucket exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        // Extend the list if necessary
        while (bucketsByLabel.size() <= 0) {
            bucketsByLabel.add(new HashSet<>());
        }
        bucketsByLabel.set(0, target);
    }

    try {
        for (int vertex : source) {
            target.add(vertex);
            if (vertex >= 0 && vertex < labels.size()) {
                labels.set(vertex, 0);
            }
        }
        source.clear();
    } catch (Exception e) {
        // Wrap any unexpected runtime exception
        throw new RuntimeException("Error while reloading buckets", e);
    }
