public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null || sub.isEmpty()) {
        return 0;
    }
    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index += 1; // move forward to allow overlapping matches
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub) {
    // Handle null input strings as specified.
    if (str == null || sub == null) {
        return 0;
    }
    // An empty substring is considered non-occurring for this method.
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;
    // Iterate through the string and look for overlapping occurrences of sub.
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        // Move forward by one character to allow overlapping matches.
        index++;
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub) {
    // Validate inputs
    if (str == null || sub == null) {
        return 0;
    }
    if (sub.isEmpty()) {
        // An empty substring is considered to occur 0 times in this implementation
        return 0;
    }

    int count = 0;
    int index = str.indexOf(sub);
    while (index != -1) {
        count++;
        // Move past this occurrence to avoid counting the same match again
        index = str.indexOf(sub, index + sub.length());
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub){
    // Handle null inputs
    if (str == null || sub == null) {
        return 0;
    }

    // An empty substring cannot be reasonably counted; return 0
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int fromIndex = 0;
    try {
        while (true) {
            int index = str.indexOf(sub, fromIndex);
            if (index == -1) {
                break;
            }
            count++;
            // Move past this occurrence
            fromIndex = index + sub.length();
        }
    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0
        return 0;
    }

    return count;
}

public static int countOccurrencesOf(String str, String sub){
    if (str == null || sub == null) {
        return 0;
    }
    if (sub.length() == 0) {
        return 0;
    }
    int count = 0;
    int idx = 0;
    while ((idx = str.indexOf(sub, idx)) != -1) {
        count++;
        idx += sub.length();
    }
    return count;
}

