protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new IllegalArgumentException("buffer must not be null");
    }
    try {
        if (array == null) {
            // Though the comment says array is not null, handle defensively
            buffer.append("null");
            return;
        }
        if (array.length == 0) {
            buffer.append("{}");
            return;
        }
        buffer.append("{");
        for (int i = 0; i < array.length; i++) {
            if (i > 0) {
                buffer.append(", ");
            }
            // Format each byte as two-digit hexadecimal
            buffer.append(String.format("0x%02X", array[i] & 0xFF));
        }
        buffer.append("}");
    } catch (Exception e) {
        // Append a placeholder in case of unexpected errors
        buffer.append("[error appending byte array]");
    }
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }
    if (array == null) {
        throw new IllegalArgumentException("array cannot be null");
    }
    buffer.append("[");
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(", ");
        }
        int unsigned = array[i] & 0xFF;
        buffer.append(String.format("0x%02X", unsigned));
    }
    buffer.append("]");
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new NullPointerException("buffer must not be null");
    }
    if (array == null) {
        if (fieldName != null && !fieldName.isEmpty()) {
            buffer.append(fieldName).append("=<null>");
        } else {
            buffer.append("<null>");
        }
        return;
    }
    if (fieldName != null && !fieldName.isEmpty()) {
        buffer.append(fieldName).append('=');
    }
    buffer.append('[');
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(',');
        }
        int unsigned = array[i] & 0xFF;
        if (unsigned < 16) {
            buffer.append('0');
        }
        buffer.append(Integer.toHexString(unsigned).toUpperCase());
    }
    buffer.append(']');
}

