        if (i > 0) {
            buffer.append(", ");
        }
        buffer.append(array[i]);
    }
    buffer.append(']');
}

@Override
public boolean hasNext() {
    // Guard against uninitialized state
    if (visited == null || graph == null) {
        throw new IllegalStateException("Graph iterator has not been initialized");
    }
    try {
        // Return true if there are still vertices that haven't been visited
        return visited.size() < graph.getVertices().size();
    } catch (Exception e) {
        // Wrap unexpected problems so the caller can detect a failure
        throw new RuntimeException("Error determining presence of unvisited vertices", e);
    }
}

@Override
public boolean hasNext() {
    if (visited == null) return false;
    for (boolean v : visited) {
        if (!v) {
            return true;
        }
    }
    return false;
}

@Override
public boolean hasNext() {
    try {
        // Return false if the internal collections are not initialized
        if (vertices == null || visitedVertices == null) {
            return false;
        }

        // The iterator is still "has next" if there is at least one vertex that has not
        // been visited yet.
        for (Object vertex : vertices) {
            if (!visitedVertices.contains(vertex)) {
                return true;
            }
        }

        // If we got through all vertices without finding an unvisited one, we are done.
        return false;
    } catch (Exception e) {
        // In the event of an unexpected error (e.g., concurrent modification etc.)
        // we conservatively assume there are no more unvisited vertices.
        return false;
    }
}

@Override public boolean hasNext(){
    try {
        // If the tracker of visited vertices isn’t initialized, assume none left.
        if (visited == null) {
            return false;
        }
        // Iterate over the visited array and return true upon encountering any unvisited vertex.
        for (boolean v : visited) {
            if (!v) {
                return true;
            }
        }
    } catch (Exception e) {
        // Any runtime issue should result in a conservative "no more elements" answer.
        return false;
    }
    return false;
}

@Override
public boolean hasNext() {
    try {
        // If the collection of all vertices is not available, no unvisited vertices can be reported
        if (vertices == null) {
            return false;
        }
        // If no tracking of visited vertices exists, assume every vertex is unvisited
        if (visited == null) {
            return !vertices.isEmpty();
        }
        // Scan for the first vertex that has not yet been visited
        for (V vertex : vertices) {
            if (!visited.contains(vertex)) {
                return true;
            }
        }
        // All vertices have been visited
        return false;
    } catch (Exception e) {
        throw new RuntimeException("Failed to determine if there are unvisited vertices", e);
    }
}

private void pop(final int elements) {
    // No operation if no elements are requested
    if (elements <= 0) {
        return;
    }

    // Defensive check: ensure we do not pop more items than are present
    if (elements > outputFrameStack.size()) {
        throw new IllegalArgumentException(
            "Attempting to pop " + elements + " elements from the output frame stack, which contains only " 
            + outputFrameStack.size() + " elements."
        );
    }

    // Remove the specified number of elements from the top of the stack
    for (int i = 0; i < elements; i++) {
        outputFrameStack.pop();
    }
}

private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop cannot be negative: " + elements);
    }
    if (elements > outputStack.size()) {
        throw new IllegalStateException(
                "Attempted to pop " + elements + " elements, but only " + outputStack.size() + " are on the stack.");
    }
    for (int i = 0; i < elements; i++) {
        outputStack.pop();
    }
}

private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non‑negative: " + elements);
    }
    if (elements > outputStack.size()) {
        throw new IllegalArgumentException(
            "attempted to pop " + elements + " elements, but only " +
            outputStack.size() + " are available");
    }
    for (int i = 0; i < elements; i++) {
        outputStack.pop(); // removes the top element of the stack
    }
}

private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non-negative");
    }
    if (outputFrameStack == null) {
        throw new IllegalStateException("Output frame stack is not initialized");
    }
    try {
        for (int i = 0; i < elements; i++) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Cannot pop from an empty output frame stack");
            }
            outputFrameStack.pop();
        }
    } catch (RuntimeException e) {
        throw new IllegalStateException("Failed to pop " + elements + " elements from output frame stack", e);
    }
}

