public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');
    // Extension exists only if a dot occurs after the last slash and is not the last character
    if (lastDot > lastSlash && lastDot < path.length() - 1) {
        return path.substring(0, lastDot);
    }
    return null;
}

public static String stripFilenameExtension(String path){
    try {
        if (path == null) {
            return null;
        }
        int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
        int lastDot = path.lastIndexOf('.');
        if (lastDot <= lastSlash || lastDot == -1) {
            return null;
        }
        // Handle hidden files like ".bashrc" which have no extension
        if (lastSlash == -1 && lastDot == 0) {
            return null;
        }
        return path.substring(0, lastDot);
    } catch (Exception e) {
        return null;
    }
}

