    int lastDot = fileName.lastIndexOf('.');
    // No dot found, or dot is the first character (e.g., ".bashrc") → no extension
    if (lastDot <= 0) {
        return null;
    }

    // Compute the index of the dot within the original path
    int dotIndexInPath = lastSlash >= 0 ? lastSlash + 1 + lastDot : lastDot;

    // Return the path up to, but not including, the dot
    return path.substring(0, dotIndexInPath);
}

