private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null input gracefully.
    if (bounds == null) {
        return new Pair<>(new ArrayList<Integer>(), 0L);
    }

    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long totalSum = 0L;
    long runningSum = 0L;

    // Iterate from the end to compute suffix sums.
    for (int i = bounds.size() - 1; i >= 0; i--) {
        Integer valObj = bounds.get(i);
        long val = (valObj == null) ? 0L : valObj.longValue();
        runningSum += val;
        // Cast to int for the suffix list; overflow is possible but conforms to the required return type.
        suffixSums.add(0, (int) runningSum);
    }

    // Compute the total sum.
    for (Integer valObj : bounds) {
        totalSum += (valObj == null) ? 0L : valObj.longValue();
    }

    return new Pair<>(suffixSums, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long currentSum = 0L;

    // Compute suffix sums from the end
    for (int i = n - 1; i >= 0; i--) {
        currentSum += bounds.get(i);
        // It's safe to cast to Integer as bounds should fit into int range
        suffix.add((int) currentSum);
    }
    // The list is built in reverse order, so reverse it
    Collections.reverse(suffix);

    // Total sum
    long totalSum = 0L;
    try {
        for (Integer val : bounds) {
            totalSum += val;
        }
    } catch (Exception e) {
        // In case of any unexpected exception during sum computation, fallback to 0
        totalSum = 0L;
    }

    return new Pair<>(suffix, totalSum);
}

