private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match.
    if (str == null) {
        return prefix == null;
    }
    // If prefix is null but string is not, it's not a match.
    if (prefix == null) {
        return false;
    }
    int prefixLen = prefix.length();
    int strLen = str.length();
    // If the prefix is longer than the string, it can't match.
    if (prefixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        // regionMatches with ignoreCase=true performs a case-insensitive comparison.
        return str.regionMatches(true, 0, prefix, 0, prefixLen);
    } else {
        return str.startsWith(prefix);
    }
}

