        if (required > buf.length) {
            int newCapacity = buf.length << 1; // double the capacity
            if (newCapacity <= length || newCapacity < required) {
                newCapacity = required; // ensure enough space
            }
            byte[] newBuf = new byte[newCapacity];
            System.arraycopy(buf, 0, newBuf, 0, length);
            buf = newBuf;
