    for (K key : keys) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<? super K> c = (Comparable<? super K>) key;
            sorted.add(c);
        } catch (ClassCastException e) {
            // If a key is not Comparable we cannot compute bounds for it
            // We'll mark its position with a sentinel value (-1)
            sorted.add(null);
        }
    }
    // Sort only the non-null entries; nulls stay at the end
    sorted.sort((a, b) -> {
        if (a == null && b == null) return 0;
        if (a == null) return 1;
        if (b == null) return -1;
        return a.compareTo((K) b);
    });

    // Prepare the result list
    List<Integer> bounds = new ArrayList<>(keys.size());

    for (K key : keys) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<? super K> ckey = (Comparable<? super K>) key;
            // binary search on the sorted list
            int index = Collections.binarySearch(sorted, ckey);
            if (index < 0) {
                // key not found, negative insertion point
                bounds.add(-(index + 1) - 1); // the maximum index that is lower than the insertion point
            } else {
                // key found: we need the last occurrence of this key
                int last = index;
                while (last + 1 < sorted.size() && sorted.get(last + 1).compareTo(ckey) == 0) {
                    last++;
                }
                bounds.add(last);
            }
        } catch (ClassCastException e) {
            bounds.add(-1); // sentinel for non-comparable keys
        } catch (Exception e) {
            // For any unforeseen runtime exception, also use sentinel
            bounds.add(-1);
        }
    }

    return bounds;
}

