public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    // Use a deque as a stack for path components
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    boolean isAbsolute = path.startsWith("/");
    // Split the base path into components
    String[] baseParts = path.split("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.removeLast();
            } else if (!isAbsolute) {
                // In a relative path, we keep leading ".."
                stack.addLast("..");
            }
            // If absolute and stack is empty, ignore further ".." (can't go above root)
        } else {
            stack.addLast(part);
        }
    }
    // Split and apply the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.removeLast();
            } else if (!isAbsolute) {
                stack.addLast("..");
            }
            // For absolute paths, ignore if at root
        } else {
            stack.addLast(part);
        }
    }
    // Construct the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append('/');
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append('/');
        }
    }
    // Handle special cases
    if (result.length() == 0) {
        // If nothing is left, return "." for relative, "/" for absolute
        return isAbsolute ? "/" : ".";
    }
    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non‑null");
    }
    // Determine if the original path was absolute
    boolean pathIsAbsolute = path.startsWith("/");
    Deque<String> components = new ArrayDeque<>();

    // Split the original path into components, ignoring empty parts
    for (String p : path.split("/")) {
        if (!p.isEmpty()) {
            components.add(p);
        }
    }

    // Process the relative path segment by segment
    for (String r : relativePath.split("/")) {
        if (r.isEmpty() || r.equals(".")) {
            continue; // Skip empty or explicit current directory
        }
        if (r.equals("..")) {
            if (!components.isEmpty()) {
                components.removeLast(); // Move up one level
            }
            continue;
        }
        components.add(r); // Normal directory/file name
    }

    // Reconstruct the final path
    StringBuilder sb = new StringBuilder();
    if (pathIsAbsolute) {
        sb.append("/");
    }
    Iterator<String> it = components.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath cannot be null");
    }

    // If the relative path is actually absolute (starts with '/'), treat it as absolute
    if (relativePath.startsWith("/")) {
        String[] parts = relativePath.split("/");
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!result.isEmpty()) {
                    result.remove(result.size() - 1);
                }
            } else {
                result.add(part);
            }
        }
        if (result.isEmpty()) {
            return "/";
        }
        return "/" + String.join("/", result);
    }

    // Normal relative processing
    String base = path;
    if (base.endsWith("/")) {
        base = base.substring(0, base.length() - 1);
    }

    java.util.List<String> stack = new java.util.ArrayList<>();
    String[] baseParts = base.split("/");
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }

    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    String result = String.join("/", stack);
    if (path.startsWith("/")) {
        return result.isEmpty() ? "/" : "/" + result;
    } else {
        return result;
    }
}

