static String[] toNoNullStringArray(Object[] array){
    if (array == null || array.length == 0) {
        return new String[0];
    }
    // Collect non-null elements that are Strings
    java.util.ArrayList<String> list = new java.util.ArrayList<>(array.length);
    for (Object obj : array) {
        if (obj != null) {
            if (obj instanceof String) {
                list.add((String) obj);
            } else {
                // If the element is not a String, skip it or convert if desired.
                // Here we choose to skip non-string elements to avoid ClassCastException.
                continue;
            }
        }
    }
    // If no non-null elements were found, return an empty array
    if (list.isEmpty()) {
        return new String[0];
    }
    // Convert the list to an array
    return list.toArray(new String[0]);
}

