    return Math.max(lastUnixSep, lastWindowsSep);
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastDotIndex = filename.lastIndexOf('.');
    if (lastDotIndex == -1) {
        return -1; // No dot found
    }

    // Find the last path separator (Unix '/' or Windows '\')
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(lastSlash, lastBackslash);

    // Ensure the dot appears after the last separator (i.e., not part of a directory name)
    if (lastDotIndex > lastSeparatorIndex) {
        return lastDotIndex;
    }

    return -1; // Dot is part of a directory name or before a separator
}

