public boolean isExpired(long timestamp, long expiredThreshold) {
    // Sanity checks – a non‑positive threshold means never expire
    if (expiredThreshold <= 0) {
        return false;
    }
    try {
        long current = System.currentTimeMillis();
        // If the current time is more than the threshold after the
        // provided timestamp, the metrics are considered expired.
        // A negative difference (timestamp in the future) should not
        // cause expiration.
        return (current - timestamp) > expiredThreshold;
    } catch (Throwable t) {
        // In case of any unexpected runtime issue, conservatively
        // decide not to expire to avoid accidental cache removal.
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            // A non‑positive threshold is considered expired.
            return true;
        }
        long currentTime = System.currentTimeMillis();
        long diff = currentTime - timestamp;
        if (diff < 0) {
            // Timestamp is in the future – treat as not expired.
            return false;
        }
        return diff >= expiredThreshold;
    } catch (Exception e) {
        // On error, conservatively do not expire the metric.
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold <= 0) {
        throw new IllegalArgumentException("expiredThreshold must be positive");
    }

    long currentTime = System.currentTimeMillis();

    // Treat negative timestamps as immediately expired
    if (timestamp < 0) {
        return true;
    }

    // If timestamp is in the future, it cannot be expired
    if (timestamp > currentTime) {
        return false;
    }

    return (currentTime - timestamp) > expiredThreshold;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate threshold
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("expiredThreshold must be non‑negative");
    }
    // Current system time in milliseconds
    long currentTime = System.currentTimeMillis();

    // If timestamp is invalid (non‑positive), consider it expired
    if (timestamp <= 0) {
        return true;
    }

    // Calculate elapsed time safely
    long elapsedMillis;
    try {
        elapsedMillis = Math.subtractExact(currentTime, timestamp);
    } catch (ArithmeticException e) {
        // Overflow indicates a very old timestamp; treat as expired
        return true;
    }

    // If elapsed time is greater than or equal to the threshold, it is expired
    return elapsedMillis >= expiredThreshold;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate input parameters
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp cannot be negative");
    }
    if (expiredThreshold <= 0) {
        throw new IllegalArgumentException("expiredThreshold must be positive");
    }

    long currentTime = System.currentTimeMillis();
    long elapsed = currentTime - timestamp;

    // If the elapsed time is negative (timestamp in the future) or overflow results in negative,
    // consider the metric as not expired.
    if (elapsed < 0) {
        return false;
    }

    return elapsed > expiredThreshold;
}

Edge edgeToNext() {
    // Retrieve the previously returned node and the node that will be returned next
    Node prevNode = this.prevNode; // previously returned node
    Node nextNode = this.nextNode; // node that will be returned next

    // If either node is missing, we cannot create an edge
    if (prevNode == null || nextNode == null) {
        return null;
    }

    // If either node is virtual, replace it with its real counterpart
    if (prevNode.isVirtual()) {
        try {
            prevNode = prevNode.getRealNode();
        } catch (Exception e) {
            // If unable to resolve to a real node, return null
            return null;
        }
    }

    if (nextNode.isVirtual()) {
        try {
            nextNode = nextNode.getRealNode();
        } catch (Exception e) {
            // If unable to resolve to a real node, return null
            return null;
        }
    }

    // Construct and return the edge between the two (real) nodes
    try {
        return new Edge(prevNode, nextNode);
    } catch (Exception e) {
        // Safely propagate any construction failures
        return null;
    }
}

