protected void append(LoggingEvent event) {
    // Guard against a null event
    if (event == null) {
        return;
    }

    // Obtain a formatted message.  If a Layout is configured, use it;
    // otherwise fall back to the event's message string.
    String formattedMessage;
    try {
        if (layout != null) {
            formattedMessage = layout.format(event);
        } else {
            formattedMessage = event.getMessage() != null
                    ? event.getMessage().toString()
                    : "";
        }
    } catch (Exception fmtEx) {
        // If formatting fails we still want to send a basic message
        formattedMessage = event.getMessage() != null
                ? event.getMessage().toString()
                : "";
    }

    // Write the formatted message to each connected client
    // We assume a thread-safe collection of client writers.
    // Clients may be represented by a PrintWriter, BufferedWriter, or similar.
    // We also handle I/O errors gracefully by removing bad clients.
    Iterator<?> it = clients.iterator(); // clients may be Set<PrintWriter> or similar
    while (it.hasNext()) {
        try {
            Object writerObj = it.next();
            if (writerObj instanceof PrintWriter) {
                PrintWriter writer = (PrintWriter) writerObj;
                writer.println(formattedMessage);
                writer.flush();
            } else if (writerObj instanceof BufferedWriter) {
                BufferedWriter writer = (BufferedWriter) writerObj;
                writer.write(formattedMessage);
                writer.newLine();
                writer.flush();
            } else if (writerObj instanceof OutputStream) {
                OutputStream out = (OutputStream) writerObj;
                out.write((formattedMessage + System.lineSeparator()).getBytes());
                out.flush();
            } else {
                // Unknown writer type – skip it
                continue;
            }
        } catch (IOException ioEx) {
            // If we cannot write to this client, remove it from the collection
            it.remove();
        } catch (RuntimeException rtEx) {
            // Unexpected runtime errors – skip this client but keep others alive
            it.remove();
        }
    }

    // Note: if 'clients' holds objects that are safe for concurrent modifications,
    // the iterator removal above may need to use a concurrent collection or alternative
    // handling, but this implementation assumes a simple collection.
}

protected void append(LoggingEvent event) {
    // Defensive check for null event
    if (event == null) {
        return;
    }

    // Obtain the formatted log message; fall back to toString() if necessary
    String message;
    try {
        // Most logging frameworks expose a formatted message accessor
        message = event.getFormattedMessage();
    } catch (NoSuchMethodError | Exception e) {
