    }

    // Iterate over all connected clients and send the log message
    for (Object clientObj : clients) { // 'clients' is assumed to be a field in the enclosing class
        try {
            // The client is expected to provide a writable interface (e.g. java.io.Writer or Socket)
            if (clientObj instanceof java.io.Writer) {
                java.io.Writer writer = (java.io.Writer) clientObj;
                writer.write(message);
                writer.flush();
            } else if (clientObj instanceof java.io.OutputStream) {
                java.io.OutputStream out = (java.io.OutputStream) clientObj;
                out.write(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                out.flush();
            } else {
                // Unsupported client type; skip or log the issue
                System.err.println("Unsupported client type for logging: " + clientObj.getClass().getName());
            }
        } catch (Exception e) {
