protected void append(LoggingEvent event) {
    // Guard against null events to avoid NPEs
    if (event == null) {
        return;
    }

    // Retrieve the rendered message from the event.
    // Log4j 1.x uses getRenderedMessage(); Log4j 2.x uses getMessage() (which returns a Message object)
    // Use reflection to support both if necessary.
    String message;
    try {
        // Try Log4j 1.x API
        message = event.getRenderedMessage();
    } catch (Throwable t1) {
        // Fallback to Log4j 2.x
        try {
            message = event.getMessage().getFormattedMessage();
        } catch (Throwable t2) {
            // If both fail, fall back to toString() as a last resort
            message = event.toString();
        }
    }

    // Send the message to all connected clients.  Assume the class has a collection
    // named `clients` that holds objects with a `write(String)` or similar method.
    if (clients == null || clients.isEmpty()) {
        return;
    }

    for (Object client : clients) {
        try {
            // Try the most common Servlet/WebSocket write signatures.
            if (client instanceof java.io.Writer) {
                ((java.io.Writer) client).write(message + "\n");
                ((java.io.Writer) client).flush();
            } else if (client instanceof java.io.OutputStream) {
                ((java.io.OutputStream) client).write((message + "\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));
                ((java.io.OutputStream) client).flush();
            } else if (client instanceof java.util.function.Consumer) {
                ((java.util.function.Consumer<String>) client).accept(message);
            } else if (client.getClass().getMethod("write", String.class) != null) {
                client.getClass().getMethod("write", String.class).invoke(client, message + "\n");
            } else {
                // If the client doesn't provide a standard write method, skip it.
            }
        } catch (Exception e) {
            // Log the exception internally and continue with the next client.
            // Use the errorHandler from AppenderSkeleton if available, otherwise fallback.
            if (errorHandler != null) {
                errorHandler.error("Failed to write log to client: " + e.getMessage(), e, 0, event);
            } else {
                System.err.println("Failed to write log to client: " + e.getMessage());
                e.printStackTrace();
            }
        }
    }
}

