private void checkIfPackedField() throws IOException {
    // If we are already reading a packed field, nothing more to do.
    if (inPackedField) {
        return;
    }

    // The tag contains the field number shifted left by 3 bits and the wire type in the lower 3 bits.
    int wireType = currentTag & 0x7;
    // Packed repeated fields use wire type 2 (length-delimited). Only need to act in that case.
    if (wireType == 2) { // LENGTH_DELIMITED
        int fieldNumber = currentTag >>> 3;
        // Verify whether this field is a packed repeated field according to the descriptor.
        if (isPackedField(fieldNumber)) {
            // Read the length prefix that bounds the packed data and set a limit for the stream.
            int length = readRawVarint32();
            pushLimit(length);
