private void checkIfPackedField() throws IOException {
    // Determine if the current field was encoded as a length‑delimited packed message.
    // If so, prepare the internal state so that subsequent reads will consume the packed
    // data correctly.
    // The wire type for a packed field is always LENGTH_DELIMITED (value 2).
    final int wireType = this.tag & 0x07;
    if (wireType == 2 /* LENGTH_DELIMITED */ && this.fieldDescriptor != null && this.fieldDescriptor.isPacked()) {
        // Record that we are in packed mode and cache the number of bytes that belong to the packed field.
        this.inPackedMode = true;
        // The length of the packed data is encoded as an unsigned varint immediately
        // after the tag.  Read it and store it so that subsequent getRaw*() calls
        // can enforce the boundary.
        try {
            this.remainingPackedBytes = this.readRawVarint32();
        } catch (IOException e) {
            // Propagate IO errors so that callers can react (e.g. fail the parse).
            throw e;
        }
    } else {
        // Not a packed field; clear any packing state that might still be set.
        this.inPackedMode = false;
        this.remainingPackedBytes = 0;
    }
}

private void checkIfPackedField() throws IOException {
    /* Packed repeated fields are stored as length‑delimited fields
     * (wire type 2 in protobuf encoding).  This method is invoked
     * after the tag has been read and the wire type has been stored
     * in the `wireType` field.  If the wire type is length‑delimited,
     * we assume the field contains a packed repeated value and we
     * adjust the internal state accordingly. */
    if (wireType == WIRETYPE_LENGTH_DELIMITED) {
        // Mark that we are currently parsing a packed field.
        packedField = true;

        // Read the number of bytes that make up the packed block.
        int packedLength = readRawVarint32();
        if (packedLength < 0) {
            throw new IOException("Negative length for packed field");
        }

        // Push a new limit so that we do not read past the end of
        // the packed data.  The previous limit can be restored
        // later when the packed block is finished.
        packedLimit = pushLimit(packedLength);
    } else {
        packedField = false;   // Not a packed field.
    }
}

public int readTag() throws IOException {
