public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    // Read a varint (field tag) from the underlying InputStream `input`.
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {            // EOF reached before any bytes were read
            return 0;             // Protocols use 0 to indicate end of message
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {    // Last byte of the varint
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint");
}

