        return 0;
    }
}

public int readTag() throws IOException {
    int b = input.read();
    if (b == -1) {
        // Reached EOF before any bytes were read.
        return 0;
    }
    int tag = b & 0x7F;
    if ((b & 0x80) == 0) {
        // Single byte tag.
        return tag;
    }
    int shift = 7;
    while (shift < 32) {
        b = input.read();
        if (b == -1) {
            // Unexpected EOF in the middle of a varint.
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    throw new IOException("Malformed tag: too many bytes");
}

