        // Validate the offsets against the total length.
        if (startOffset > endOffset || startOffset < 0 || endOffset >= totalLength) {
            return "bytes */" + totalLength;
        }

        return String.format("bytes %d-%d/%d", startOffset, endOffset, totalLength);
    } catch (Exception e) {
