public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Validate input file
    if (file == null) {
        throw new IllegalArgumentException("File must not be null.");
    }
    if (!file.exists() || !file.isFile() || !file.canRead()) {
        throw new IOException("Cannot read file: " + file.getAbsolutePath());
    }

    // Prepare the result list
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Prepare a quick-access list for ranges if provided
    boolean filterByRange = timeRanges != null && !timeRanges.isEmpty();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip empty lines
            if (line.trim().isEmpty()) {
                continue;
            }

            // Attempt to parse a timestamp from the beginning of the line.
            // This implementation assumes the line starts with a timestamp followed by a separator (e.g., a colon).
            // Example format: "1629379200: Some thread data ..."
            long timestamp;
            String dataPart;
            int sepIndex = line.indexOf(':');
            if (sepIndex > 0) {
                String tsString = line.substring(0, sepIndex).trim();
                try {
                    timestamp = Long.parseLong(tsString);
                } catch (NumberFormatException e) {
                    // If timestamp parsing fails, skip this line
                    continue;
                }
                dataPart = line.substring(sepIndex + 1).trim();
            } else {
                // If no separator present, we consider the whole line as data without a timestamp
                // This snapshot will be added only if no range filtering is required
                dataPart = line.trim();
                timestamp = -1L;
            }

            // Determine if this snapshot falls within any of the requested time ranges
            if (filterByRange) {
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime(); // Assumes getter exists
                    long end = range.getEndTime();     // Assumes getter exists
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (!inRange) {
                    continue; // Skip snapshots outside all ranges
                }
            }

            // Create a ThreadSnapshot instance
            // The ThreadSnapshot class is expected to have a suitable constructor or factory method.
            // Here we use a placeholder constructor that takes timestamp and raw data.
            try {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, dataPart);
                snapshots.add(snapshot);
            } catch (Exception e) {
                // If any exception occurs while creating a snapshot (e.g., constructor not found),
                // we log and skip this entry. Logging is omitted here for brevity.
                continue;
            }
        }
    }

    return snapshots;
}

